CREATE SCHEMA core;
CREATE SCHEMA app;

REVOKE CREATE ON SCHEMA core FROM PUBLIC;
REVOKE USAGE ON SCHEMA core FROM PUBLIC;
REVOKE CREATE ON SCHEMA app FROM PUBLIC;
REVOKE USAGE ON SCHEMA app FROM PUBLIC;

ALTER DEFAULT PRIVILEGES IN SCHEMA app REVOKE SELECT ON TABLES FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA app REVOKE INSERT ON TABLES FROM PUBLIC;
